const listWorkouts = `-- name: ListWorkouts :many

SELECT id, user_id, template_id, name, workout_date,
       COALESCE(notes,'') AS notes,
       COALESCE(client_uuid,'') AS client_uuid, created_at FROM workouts
WHERE (CAST($1 AS BIGINT) IS NULL OR user_id = $1)
  AND (CAST($2 AS TEXT) IS NULL OR workout_date >= $2)
  AND (CAST($3 AS TEXT) IS NULL OR workout_date <= $3)
ORDER BY workout_date DESC, id DESC
`

type ListWorkoutsParams struct {
	UserID   sql.NullInt64
	DateFrom sql.NullString
	DateTo   sql.NullString
}

type ListWorkoutsRow struct {
	ID          int64
	UserID      int64
	TemplateID  sql.NullInt64
	Name        string
	WorkoutDate string
	Notes       string
	ClientUuid  string
	CreatedAt   time.Time
}

// =========================================================================
// workouts
// =========================================================================
func (q *Queries) ListWorkouts(ctx context.Context, arg ListWorkoutsParams) ([]ListWorkoutsRow, error) {
	rows, err := q.db.QueryContext(ctx, listWorkouts, arg.UserID, arg.DateFrom, arg.DateTo)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListWorkoutsRow{}
	for rows.Next() {
		var i ListWorkoutsRow
		if err := rows.Scan(
			&i.ID,
			&i.UserID,
			&i.TemplateID,
			&i.Name,
			&i.WorkoutDate,
			&i.Notes,
			&i.ClientUuid,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

